independent.solution:
funnels = {'email': [500, 300, 150, 90], 'search': [2000, 800, 240, 120]}
overall = {}
for name, c in funnels.items():
    conv = [b / a for a, b in zip(c, c[1:])]
    print(name + ': step ' + str(conv.index(min(conv)) + 1))
    overall[name] = c[-1] / c[0]
print('lowest overall: ' + min(overall, key=overall.get))
